  const roots = [claudeProjectsRoot(), codexSessionsRoot()];
  const watchers: FSWatcher[] = [];
  const timers = new Map<string, ReturnType<typeof setTimeout>>();
  let stopped = false;

  // `onSettled` recharge `CursorStore`/`DedupSet` FRAIS À CHAQUE APPEL (au lieu
  // de fermer sur des instances chargées une seule fois au démarrage) : dans
  // un process qui vit des mois (LaunchAgent `KeepAlive`), la sweep
  // périodique (`runIngest`, plus bas) charge AUSSI ses propres instances
  // fraîches à chaque passe — un `onSettled` sur un état périmé écraserait au
  // `.save(true)` ce que la sweep vient d'écrire sur disque. `.load()` est bon
  // marché (relit un petit fichier JSON), ce recoût est donc sûr.
  const onSettled = async (runtime: SessionRuntime, filePath: string) => {
    if (stopped) return;
    let st: import('node:fs').Stats;
    try {
      st = await stat(filePath);
    } catch {
      return; // deleted/renamed away
    }
    if (!st.isFile()) return;
    const cand: Candidate = {
      runtime,
      filePath,
      mtimeMs: st.mtimeMs,
      sizeBytes: st.size,
    };
    try {
      const cursors = await CursorStore.load();
      const dedup = await DedupSet.load();
      const result = await ingestOne(cand, cursors, dedup);
      if (result.status === 'captured') {
        await cursors.save(true);
        await dedup.save(true);
        publish({ type: 'projects-changed' });
      } else if (result.status === 'blocked' || result.status === 'duplicate') {
        await cursors.save(true);
        await dedup.save(true);
      }
    } catch {
      // Swallow — the sweep is the safety net.
    }
  };

  for (const root of roots) {
    const runtime = runtimeForRoot(root);
    try {
      await mkdir(root, { recursive: true });
    } catch {
      // Source root may legitimately not exist (e.g. Codex never used).
    }
    const onChange = (_event: string, filename: string | Buffer | null) => {
      const rel =
        typeof filename === 'string'
          ? filename
          : filename
          ? filename.toString()
          : '';
      if (!rel) return;
      const base = path.basename(rel);
      if (base.includes('.tmp-')) return; // atomic-write temp
      if (!matchesRuntime(base, runtime)) return;
      const filePath = path.join(root, rel);

      const key = filePath;
      const existing = timers.get(key);
      if (existing) clearTimeout(existing);
      timers.set(
        key,
        setTimeout(() => {
          timers.delete(key);
          void onSettled(runtime, filePath);
        }, DEBOUNCE_MS),
      );
    };

    let watcher: FSWatcher;
    try {
      watcher = watchFactory(root, { recursive: true });
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn(
        `[capture] watch disabled for ${root} (recursive unsupported): ${String(
          err,
        )}`,
      );
      continue;
    }
    watcher.on('change', onChange);
    watcher.on('error', (err) => {
      // eslint-disable-next-line no-console
      console.warn(`[capture] watcher error (${root}): ${String(err)}`);
    });
    watchers.push(watcher);
