/**
 * Backfill origins — rank-1 ("inferred") capture, batch form (chantier
 * provenance-session, D3, lot 6; hardened by the P2/P3 fixes below, revue
 * adversariale du 2026-09-08).
 *
 * PURE orchestration over `findSessionsMentioningAny` (`reverseIndex.ts`):
 * given a list of already-loaded records (each carrying its id, creation
 * time, and whatever `origin` is already on disk), decide — per record —
 * whether it needs backfilling (origin absent or ranked below `inferred`),
 * search the reverse index, and report ONE OF four verdicts:
 *
 *   - a SINGLE candidate session ⇒ stamp `capturedBy: 'inferred'` via the
 *     caller-supplied `stamp` callback (never a direct file write from here —
 *     see `stampConversationOrigin`/`stampChipOrigin`, the actual store choke
 *     points);
 *   - zero candidates ⇒ `NOT_FOUND`, nothing written;
 *   - two or more DISTINCT candidates ⇒ `AMBIGUOUS`, nothing written — D3 is
 *     explicit that ambiguity must never be resolved by guessing;
 *   - a single candidate but `stamp` itself reports failure (constat bonus,
 *     revue adversariale) ⇒ `STAMP_FAILED`, counted separately from
 *     `stamped` — a race where the record vanished/changed between listing
 *     and stamping must never inflate the "genuinely written" count.
 *
 * `kind` is a free-form string (not narrowed to `'conversation' | 'chip'`)
 * so a later chantier can feed this the same pipeline for `'galley'` /
 * `'reminder'` records without touching this file — every caller already
 * supplies its own `stamp` callback, so this module never needs to know
 * which store a given `kind` actually writes to.
 *
 * BATCHING (constat 1, revue adversariale): every eligible record's search
 * is issued as ONE needle in a SINGLE `findMany` call — never one call per
 * record. `reverseIndex.ts`'s `findSessionsMentioningAny` is what actually
 * turns that into one corpus traversal regardless of batch size; this
 * module's job is just to build the needle list and route each id's
 * resulting candidates back to its own record, in the original record
 * order (never needle-iteration order, which a `Map` does not guarantee for
 * a caller relying on insertion order across concurrent fills).
 *
 * Kept dependency-injectable (`deps.find`, `deps.now`) so the unit test never
 * touches a real `~/.claude`/`~/.codex` tree or the real clock.
 */
import { CAPTURE_RANK, type AgentOrigin, type CaptureLayer, type OriginSource } from '../../../src/types/agentOrigin';
import {
  findSessionsMentioningAny,
  defaultWindow,
  wideWindow,
  type SessionCandidate,
  type NeedleWindow,
} from './reverseIndex';

export interface BackfillRecord {
  /** Free-form record kind — 'conversation' | 'chip' today, more later. */
  kind: string;
  /** Human-readable reference for log lines (e.g. "<slug>/<id>" or "<id>"). */
  ref: string;
  /** The literal string searched for in transcripts — the record's own id. */
  id: string;
  createdAt: string;
  /** Whatever `origin` is CURRENTLY on disk — only `capturedBy` matters here. */
  capturedBy: CaptureLayer | undefined;
}

export type BackfillVerdict = 'stamped' | 'ambiguous' | 'not_found' | 'skipped' | 'stamp_failed';

export interface BackfillOutcome {
  record: BackfillRecord;
  verdict: BackfillVerdict;
  candidate?: SessionCandidate;
  candidates?: SessionCandidate[];
}

export interface BackfillSummary {
  stamped: number;
  ambiguous: number;
  notFound: number;
  skipped: number;
  /** Constat bonus (revue adversariale): a single candidate whose `stamp`
   *  callback itself reported failure (e.g. the record vanished between
   *  listing and stamping) — counted separately from `stamped` so
   *  `VERDICT: BACKFILL stamped=<n>` never over-reports genuine writes. */
