 *          tagged, in a parallel array
 *          `internal_chat_message_metadata_passthrough.content_item_kinds` —
 *          only `user.text` is the human's text. Older rollouts have no tags,
 *          so injected blocks are recognised by their shape instead.
 *       2. `event_msg` with `payload.type === 'item_completed'` and
 *          `payload.item.type === 'UserMessage'` — `item.content[]` items of
 *          `type: 'text'` (images are `image`/`local_image`, ignored).
 *   `developer`/`system` role messages are never a human prompt.
 *
 * The human's text itself can arrive wrapped: Codex Desktop prefixes ambient
 * context (`# Files mentioned by the user:`, `# In app browser:`,
 * `<in-app-browser-context …>…</in-app-browser-context>`) and then puts the
 * request under a `## My request:` / `## My request for Codex:` heading.
 * `cleanCodexUserText` unwraps that and peels a closed list of injected
 * leading blocks; a text that is NOTHING but injected context (a
 * `<task-notification>`, a `<codex_delegation>`, AGENTS.md…) is not a human
 * prompt and yields `undefined`.
 *
 * Lineage lives on the rollout's FIRST `session_meta` line — see
 * `codexLineageFromMeta` (parsed payload) and `codexLineageFromHead` (raw
 * byte prefix, for bounded listings that must not JSON-parse a ~20-50KB line).
 */

type Json = Record<string, unknown>;

function asObject(v: unknown): Json | undefined {
  return v && typeof v === 'object' && !Array.isArray(v) ? (v as Json) : undefined;
}

function asText(v: unknown): string | undefined {
  return typeof v === 'string' && v.length > 0 ? v : undefined;
}

/** Heading Codex Desktop puts in front of the human's own words when it
 *  prepends ambient context to the same message — both spellings occur
 *  (`## My request:` ~3x more often than `## My request for Codex:`). */
const REQUEST_HEADING_RE = /^## My request(?: for Codex)?:[ \t]*\n?/m;

/** Markdown headings of ambient context blocks Codex injects INTO a
 *  user-role text (never typed by the human). */
const INJECTED_HEADING_RE = /^# (AGENTS\.md instructions|Files mentioned by the user|Applications mentioned by the user|In app browser)\b/;

/**
 * Tags of blocks Codex (or a host) injects at the START of a user-role text,
 * as observed on every rollout under `~/.codex/sessions/2026/` — only these
 * are peeled, so a human prompt that happens to start with markup is left
 * intact. `command-args` is the one block whose CONTENT is the human's text
 * (a slash command's arguments): it is unwrapped, not dropped.
 */
const INJECTED_TAGS = new Set([
  'environment_context', 'user_instructions', 'INSTRUCTIONS', 'skill', 'recommended_plugins', 'turn_aborted',
  'task-notification', 'in-app-browser-context', 'codex_delegation', 'realtime_delegation',
  'command-message', 'command-name', 'local-command-stdout', 'local-command-stderr',
  'send_user_message_question_reply', 'scheduled-task', 'heartbeat', 'hook_prompt', 'subagent_notification',
  'appshot', 'image',
]);
const UNWRAPPED_TAGS = new Set(['command-args']);

/** A leading `<tag …>…</tag>` block, closed by ITS OWN tag. */
const LEADING_BLOCK_RE = /^<([A-Za-z][\w-]*)(?:\s[^>]*)?>([\s\S]*?)<\/\1>\s*/;
/** A leading self-standing marker such as `<image name=[Image #1]>`. */
const LEADING_MARKER_RE = /^<(image)(?:\s[^>]*)?\/?>\s*/;

function startsWithAmbientContext(text: string): boolean {
  if (INJECTED_HEADING_RE.test(text)) return true;
  const tag = /^<([A-Za-z][\w-]*)/.exec(text)?.[1];
  return tag !== undefined && INJECTED_TAGS.has(tag);
}

/**
 * The human's own words out of one raw user-role text, or `undefined` when
 * the text is only injected context. Never throws.
 */
export function cleanCodexUserText(raw: string): string | undefined {
  let text = raw.trim();
  // Only a text that OPENS with ambient context is split on the request
  // heading — a guardian reviewer's prompt quotes whole transcripts, headings
  // included, and must not be cut in the middle of the quote.
  if (startsWithAmbientContext(text)) {
    const heading = REQUEST_HEADING_RE.exec(text);
    if (heading) text = text.slice(heading.index + heading[0].length).trim();
  }

  // Peel known leading blocks (bounded: a pathological text cannot loop).
  for (let i = 0; i < 8; i++) {
    const block = LEADING_BLOCK_RE.exec(text);
    if (block && UNWRAPPED_TAGS.has(block[1])) {
      text = (block[2].trim() + '\n' + text.slice(block[0].length)).trim();
      continue;
    }
    if (block && INJECTED_TAGS.has(block[1])) {
      text = text.slice(block[0].length).trim();
      continue;
    }
    const marker = LEADING_MARKER_RE.exec(text);
    if (marker) {
      text = text.slice(marker[0].length).trim();
      continue;
    }
    break;
  }
  if (!text) return undefined;
  if (INJECTED_HEADING_RE.test(text)) return undefined;
  return text;
}

function firstCleanText(texts: string[]): string | undefined {
  for (const t of texts) {
    const cleaned = cleanCodexUserText(t);
    if (cleaned) return cleaned;
  }
  return undefined;
}

/**
 * The human prompt carried by ONE parsed rollout line, if any — legacy
 * `user_message`, current `item_completed`/`UserMessage`, or current
 * `response_item` user message (tagged `user.text` items only when tags are
 * present). File order decides which copy wins; both current copies hold the
 * same text.
 */
export function codexUserPromptFromLine(obj: Json): string | undefined {
  const payload = asObject(obj.payload);
  if (!payload) return undefined;

  if (payload.type === 'user_message') {
    const msg = asText(payload.message);
    return msg ? cleanCodexUserText(msg) : undefined;
  }

  if (obj.type === 'event_msg' && payload.type === 'item_completed') {
    const item = asObject(payload.item);
    if (!item || item.type !== 'UserMessage' || !Array.isArray(item.content)) return undefined;
    const texts: string[] = [];
    for (const c of item.content) {
      const block = asObject(c);
      const t = block?.type === 'text' ? asText(block.text) : undefined;
      if (t) texts.push(t);
    }
    return firstCleanText(texts);
  }

  if (obj.type === 'response_item' && payload.type === 'message' && payload.role === 'user') {
    if (!Array.isArray(payload.content)) return undefined;
    const kinds = asObject(payload.internal_chat_message_metadata_passthrough)?.content_item_kinds;
    const tagged = Array.isArray(kinds) && kinds.length === payload.content.length;
    const texts: string[] = [];
    payload.content.forEach((c, i) => {
      if (tagged && kinds[i] !== 'user.text') return;
      const t = asText(asObject(c)?.text);
      if (t) texts.push(t);
    });
    return firstCleanText(texts);
  }

  return undefined;
}

/** Which conversational turn (if any) a line counts as — legacy events and
 *  current `item_completed` items are two channels; a rollout uses one. */
export type CodexMessageChannel = 'legacy' | 'item';

export function codexMessageChannel(obj: Json): CodexMessageChannel | undefined {
  const payload = asObject(obj.payload);
  if (!payload) return undefined;
  if (payload.type === 'user_message' || payload.type === 'agent_message') {
    return obj.type === 'event_msg' ? 'legacy' : undefined;
  }
  if (obj.type === 'event_msg' && payload.type === 'item_completed') {
    const itemType = asObject(payload.item)?.type;
    if (itemType === 'UserMessage' || itemType === 'AgentMessage') return 'item';
  }
  return undefined;
}

/* -------------------------------------------------------------------------- */
/*  Lineage                                                                   */
/* -------------------------------------------------------------------------- */

export interface CodexLineage {
  /** Parent thread id (`parent_thread_id` or `forked_from_id`). */
  parentId: string;
  /**
   * True for a spawned sub-agent (`source.subagent`, e.g. a named
   * `thread_spawn` worker or an automatic `guardian` reviewer) or any
   * thread carrying an `agent_nickname`/`agent_path`; false for a plain
   * fork/continuation of the parent thread.
   */
  isSubagent: boolean;
  /** Nickname, path, or the `source.subagent.other` kind (e.g. "guardian"). */
  agentType?: string;
}

/**
 * Lineage from the FIRST `session_meta` line's parsed payload. Older Codex
 * Desktop builds (0.126) wrote the parent ONLY inside
 * `source.subagent.thread_spawn` — read there as a last resort, so this
 * reader and `codexLineageFromHead` agree on every real rollout.
 */
export function codexLineageFromMeta(payload: Json): CodexLineage | undefined {
  const subagent = asObject(asObject(payload.source)?.subagent);
  const spawn = asObject(subagent?.thread_spawn);
  const parentId =
    asText(payload.parent_thread_id) ?? asText(payload.forked_from_id) ?? asText(spawn?.parent_thread_id);
  if (!parentId) return undefined;
  const nickname =
    asText(payload.agent_nickname) ??
    asText(payload.agent_path) ??
    asText(spawn?.agent_nickname) ??
    asText(spawn?.agent_path);
  const agentType = nickname ?? asText(subagent?.other);
  return { parentId, isSubagent: Boolean(subagent || nickname), agentType };
}

const HEAD_PARENT_THREAD_RE = /[{,]"parent_thread_id":"([^"\\]+)"/;
const HEAD_FORKED_FROM_RE = /[{,]"forked_from_id":"([^"\\]+)"/;
const HEAD_SUBAGENT_RE = /[{,]"source":\{"subagent":|[{,]"agent_(?:nickname|path)":"/;

/**
 * Lineage from a raw byte PREFIX of a rollout (bounded listings). Only the
 * first line is considered. Same key priority as `codexLineageFromMeta`
 * (`parent_thread_id` — top-level, or the `thread_spawn` copy — before
 * `forked_from_id`); the parity test in `codexRollout.test.ts` holds both
 * readers to the same answer. The patterns require an unescaped `"key":"`
 * after `{`/`,`, which a key quoted INSIDE a JSON string value (always
 * `\"key\"`) can never produce. Every lineage key sits before the large
 * `base_instructions` field — within the first 384 bytes on every real
 * rollout (measured 2026-09-28, 2 818 rollouts).
 */
export function codexLineageFromHead(head: string): Pick<CodexLineage, 'parentId' | 'isSubagent'> | undefined {
  const nl = head.indexOf('\n');
  const firstLine = nl >= 0 ? head.slice(0, nl) : head;
  if (!firstLine.includes('"session_meta"')) return undefined;
  const parentId = (HEAD_PARENT_THREAD_RE.exec(firstLine) ?? HEAD_FORKED_FROM_RE.exec(firstLine))?.[1];
  if (!parentId) return undefined;
  return { parentId, isSubagent: HEAD_SUBAGENT_RE.test(firstLine) };
}
