import type { ParsedSession } from './types';

function asText(v: unknown): string | undefined {
  return typeof v === 'string' && v.length > 0 ? v : undefined;
}

/**
 * Resolve a Codex session's title (chantier provenance-session, lot 9).
 * Injected so a test can stub it out; defaults to `readCodexThreadTitle`
 * (`server/services/agentSessions/lookup.ts`) — the SAME reader the agent-
 * session lookup route already uses to read `~/.codex/session_index.jsonl`
 * (last `thread_name` for the id wins), reused here rather than duplicated.
 */
export type ResolveCodexTitle = (sessionId: string) => Promise<string | undefined>;

export async function parseCodexSession(
  filePath: string,
  content: string,
  resolveTitle: ResolveCodexTitle = readCodexThreadTitle,
): Promise<ParsedSession> {
  let sessionId = path.basename(filePath, '.jsonl');
  let cwd = '';
  let startedAt: string | undefined;
  let endedAt: string | undefined;
  let model: string | undefined;
  let firstUserPrompt: string | undefined;
  const turns = { legacy: 0, item: 0 };
  let forkOf: string | undefined;
  let subagentOf: string | undefined;
  let agentType: string | undefined;
  let isFork: boolean | undefined;
  let sawSessionMeta = false;

  const scanParts: string[] = [];

  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    let obj: Record<string, unknown>;
    try {
      obj = JSON.parse(trimmed) as Record<string, unknown>;
    } catch {
      // Skip malformed/partial lines — never abort the whole file.
      continue;
    }

    const ts =
      asText(obj.timestamp) ??
      asText((obj.payload as Record<string, unknown> | undefined)?.timestamp);
    if (ts) {
      if (!startedAt) startedAt = ts;
      endedAt = ts;
    }

    const type = obj.type;
    const payload = (obj.payload ?? {}) as Record<string, unknown>;

    if (type === 'session_meta') {
      // Identity (id/cwd) AND lineage are taken from the FIRST session_meta
      // line only (see module doc comment): a resumed/forked session's
      // rollout can re-embed the PARENT's own session_meta later in the file
      // (context replay), and that must not turn this transcript's own
      // sessionId/cwd into the parent's — `sessionId` is the store's write
      // key (see store.ts `recordPath`), so overwriting it here would file
      // this capture under the PARENT's id instead of its own.
      if (!sawSessionMeta) {
        sawSessionMeta = true;
        const id = asText(payload.id);
        if (id) sessionId = id;
        const c = asText(payload.cwd);
        if (c) cwd = c;

        const lineage = codexLineageFromMeta(payload);
        if (lineage?.isSubagent) {
          subagentOf = lineage.parentId;
          agentType = lineage.agentType;
        } else if (lineage) {
          forkOf = lineage.parentId;
          isFork = true;
        }
      }
      continue;
    }

    if (type === 'turn_context') {
      const m = asText(payload.model);
      if (m && !model) model = m;
      const c = asText(payload.cwd);
      if (c && !cwd) cwd = c;
      continue;
    }

    const channel = codexMessageChannel(obj);
    if (channel) turns[channel]++;

    const prompt = codexUserPromptFromLine(obj);
    if (prompt && !firstUserPrompt) firstUserPrompt = prompt;

    const pType = payload.type;
    // Current-format turns: the RAW text of every user/agent item is
    // scanned, like the legacy `user_message`/`agent_message` events below —
    // never only the cleaned prompt, so the scan does not depend on what the
    // preview cleaner keeps (the preview is a substring of a scanned text).
    if (channel === 'item') {
      const content = (payload.item as Record<string, unknown>).content;
      if (Array.isArray(content)) {
        for (const block of content) {
          const t = block && typeof block === 'object' ? (block as Record<string, unknown>).text : undefined;
          if (typeof t === 'string') scanParts.push(t);
        }
      }
      continue;
    }
    if (pType === 'user_message' || pType === 'agent_message') {
