/** Discover all candidate files for a runtime (unsorted). */
export async function discover(runtime: SessionRuntime): Promise<Candidate[]> {
  const root =
    runtime === 'claude' ? claudeProjectsRoot() : codexSessionsRoot();
  const files = await walk(root, (name) =>
    runtime === 'claude'
      ? name.endsWith('.jsonl')
      : name.startsWith('rollout-') && name.endsWith('.jsonl'),
  );

  const candidates: Candidate[] = [];
  for (const filePath of files) {
    try {
      const st = await stat(filePath);
      candidates.push({
        runtime,
        filePath,
        mtimeMs: st.mtimeMs,
        sizeBytes: st.size,
      });
    } catch {
      // File vanished between walk and stat — skip.
    }
  }
  return candidates;
}

export interface IngestOptions {

/**
 * Ingest a single candidate using shared cursor + dedup state. Returns the
 * store result (or a synthetic 'duplicate'). Advances the cursor to the last
 * complete newline on success; resets to 0 on truncation.
 */
export async function ingestOne(
  cand: Candidate,
  cursors: CursorStore,
  dedup: DedupSet,
  /** P2 nº3 (revue adversariale) — see `store.ts`'s `ingestFile` doc comment;
   *  built ONCE per `runIngest` pass, not per Codex candidate. */
  resolveCodexTitle?: ResolveCodexTitle,
  force = false,
): Promise<IngestResult> {
  const { runtime, filePath } = cand;
  const prior = cursors.get(filePath);

  // Cheap incremental skip: nothing changed since we last reached EOF.
  if (
    !force &&
    prior &&
    prior.byteOffset >= cand.sizeBytes &&
    prior.mtimeMs === cand.mtimeMs &&
    prior.sizeBytes === cand.sizeBytes
  ) {
    return { status: 'duplicate', runtime, sourceHash: prior.sessionId };
  }

  const { content, mtimeMs, sizeBytes } = await readSource(filePath);

  // Truncation/rotation guard: if the file shrank below our offset, re-read all.
  const truncated = prior ? prior.byteOffset > sizeBytes : false;

  // Hash the WHOLE file for stable, content-addressed dedup.
  const { createHash } = await import('node:crypto');
  const sourceHash = createHash('sha256')
    .update(content, 'utf8')
    .digest('hex');

  const advanceCursor = (sessionId: string) => {
    const buf = Buffer.from(content, 'utf8');
    const offset = lastCompleteNewlineEnd(buf);
    const cursor: Cursor = {
      path: filePath,
      runtime,
      sessionId,
      byteOffset: offset,
      mtimeMs,
      sizeBytes,
    };
    cursors.set(cursor);
  };

  if (!force && !truncated && dedup.has(sourceHash)) {
    // Already captured this exact content — idempotent skip, but keep the cursor
    // current so we do not re-read it next time.
    advanceCursor(prior?.sessionId ?? path.basename(filePath, '.jsonl'));
    return { status: 'duplicate', runtime, sourceHash };
  }

  const result = await ingestFile({
    runtime,
    filePath,
    content,
    mtimeMs,
    sizeBytes,
    resolveCodexTitle,
  });

  if (result.status === 'captured' || result.status === 'blocked') {
    // Mark the content as seen so re-runs do not reprocess it (a quarantined
    // dirty file must not be re-scanned forever).
    dedup.add(result.sourceHash);
    advanceCursor(result.sessionId ?? path.basename(filePath, '.jsonl'));
  } else if (result.status === 'empty') {
    advanceCursor(path.basename(filePath, '.jsonl'));
  }
  return result;
}

/**
 * Bounded ingest pass over BOTH runtimes. Loads cursor + dedup state, seeds the
 * dedup set from Codex imports, processes up to `cap` newest files, then
 * persists state once.
 */
export async function runIngest(opts: IngestOptions = {}): Promise<IngestSummary> {
  const cursors = await CursorStore.load();
  const dedup = await DedupSet.load();
  await dedup.seedFromCodexImports();

  // P2 nº3 (revue adversariale, chantier provenance-session): ONE streamed
  // pass over `session_index.jsonl` for the WHOLE ingest pass, reused for
  // every Codex candidate below — `parseCodexSession`'s default
  // `readCodexThreadTitle` would otherwise re-read that whole (append-only,
  // ever-growing) file once PER Codex candidate ingested.
  const codexTitleMap = await buildCodexTitleMap();
  const resolveCodexTitle: ResolveCodexTitle = async (sessionId) => codexTitleMap.get(sessionId);

  const all = [
    ...(opts.runtime === 'codex' ? [] : await discover('claude')),
    ...(opts.runtime === 'claude' ? [] : await discover('codex')),
  ];

  let filtered = all;
  if (opts.sinceMs !== undefined) {
    filtered = filtered.filter((c) => c.mtimeMs >= opts.sinceMs!);
  }
  // Newest first so a bounded pass captures the most recent activity.
  filtered.sort((a, b) => b.mtimeMs - a.mtimeMs);
  if (opts.cap !== undefined) filtered = filtered.slice(0, opts.cap);

  const summary = emptySummary();
  for (const cand of filtered) {
    summary.scanned++;
    let result: IngestResult;
    try {
      result = await ingestOne(cand, cursors, dedup, resolveCodexTitle, opts.force);
    } catch {
      // A single unreadable/odd file must not abort the whole pass — but it
      // is counted, so a pass that silently skipped files says so.
      summary.errors++;
      continue;
    }
    switch (result.status) {
      case 'captured':
        summary.captured++;
        summary.byRuntime[cand.runtime].captured++;
        break;
      case 'duplicate':
        summary.duplicates++;
        summary.byRuntime[cand.runtime].duplicates++;
        break;
      case 'blocked':
        summary.blocked++;
        summary.byRuntime[cand.runtime].blocked++;
        for (const p of result.patterns ?? []) {
          summary.blockedPatterns[p] = (summary.blockedPatterns[p] ?? 0) + 1;
        }
        break;
      case 'empty':
        summary.empty++;
        break;
    }
  }

  await cursors.save(true);
  await dedup.save(true);
  return summary;
}

