async function buildCodexSummary(
  sessionId: string,
  filePath: string | undefined,
  fileMtimeIso: string | undefined,
  hints: LookupHints,
): Promise<AgentSessionSummary> {
  const titlePromise = hints.codexTitleMap
    ? Promise.resolve(hints.codexTitleMap.get(sessionId))
    : readCodexThreadTitle(sessionId);
  const [record, rawTitle] = await Promise.all([readCaptureRecord('codex', sessionId), titlePromise]);
  const title = scrubSessionText(rawTitle);
  const resumeCommand = `codex resume ${sessionId}`;

  if (!filePath && !record && !title) {
    return { runtime: 'codex', sessionId, resumeCommand, found: false };
  }

  let preview = record?.preview;
  const lastActivityAt = fileMtimeIso ?? record?.endedAt ?? record?.startedAt;
  let host: AgentSessionHost | undefined;

  if (filePath) {
    host = await readCodexRolloutHead(filePath);
    // Also when the record has no preview: records captured before the
    // current-format fix (chip 2026-09-25-fix-codex-session-previews-in-
    // capture) carry none until re-ingested.
    if (!preview) {
      preview = buildPreview(await readCodexFirstUserPromptBounded(filePath));
    }
  }

  return {
    runtime: 'codex',
    sessionId,
    title,
    preview,
    lastActivityAt,
    transcriptPath: filePath,
    resumeCommand,
    host,
    found: true,
  };
}

