async function buildClaudeSummary(
  sessionId: string,
  filePath: string | undefined,
  fileMtimeIso: string | undefined,
  sizeBytes: number | undefined,
): Promise<AgentSessionSummary> {
  const record = await readCaptureRecord('claude', sessionId);
  const resumeCommand = `claude --resume ${sessionId}`;

  if (!filePath && !record) {
    return { runtime: 'claude', sessionId, resumeCommand, found: false };
  }

  let title: string | undefined;
  let preview = record?.preview;
  const lastActivityAt = fileMtimeIso ?? record?.endedAt ?? record?.startedAt;

  if (filePath) {
    // P1 nº1 (revue adversariale): scrub the title through the SAME
    // caviardage as preview — a prior version left title un-scrubbed right
    // next to a scrubbed preview on this very response object.
    title = scrubSessionText(await readLastCustomTitleBounded(filePath, sizeBytes ?? 0));
    if (!record) {
      preview = buildPreview(await readFirstUserPromptBounded(filePath));
    }
  }

  return {
    runtime: 'claude',
    sessionId,
    title,
